async function rpcBatchOnce(url, calls) {
  const start = rpcId;
  const payload = calls.map(([to, data]) => ({ jsonrpc: "2.0", id: ++rpcId, method: "eth_call", params: [{ to, data }, "latest"] }));
  const res = await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) });
  if (!res.ok) throw new Error("RPC HTTP " + res.status);
  const out = await res.json();
  if (!Array.isArray(out)) throw new Error("RPC batch response was not an array");
  const byId = {};
  for (const x of out) byId[x.id] = x.result || null;
  return calls.map((_, i) => byId[start + i + 1] || null);
}

async function rpcBatch(url, calls) {
  try { return await rpcBatchOnce(url, calls); }
  catch (e) { return await rpcBatchOnce(url, calls); } // one retry for transient RPC/network failures
}

async function rpcOne(url, to, data) { return (await rpcBatch(url, [[to, data]]))[0]; }

async function rpcBlock(url) {
  const res = await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "eth_blockNumber", params: [] }) });
  const j = await res.json(); return parseInt(j.result, 16);
}

async function fetchAnchors() {
  const pairsWanted = [[NATIVE_PH, USDT_INF], [QOM_INF, NATIVE_PH], [FISH_INF, USDT_INF], [FISH_INF, QOM_INF]];
  const pairAddrs = await rpcBatch(INF_RPC, pairsWanted.map(([a, b]) => [INF_FACTORY, SEL.getPair + encAddr(a) + encAddr(b)]));
  const calls = [];
  for (const pa of pairAddrs) { const d = decAddr(pa); calls.push([d, SEL.token0], [d, SEL.getReserves]); }
  const res = await rpcBatch(INF_RPC, calls);
  const info = pairsWanted.map((_, i) => {
    const pair = decPair(pairAddrs[i]); const t0 = decAddr(res[i * 2]);
    const rr = parseReservesRaw(res[i * 2 + 1]);
    if (!pair || !t0 || !rr) throw new Error(L("errAnchorPool"));
    return { pair, t0, r0: bigToNum(rr[0], 18) || 0, r1: bigToNum(rr[1], 18) || 0 };
  });
  // 42/USDT: price42 = USDT per 42
  const p42 = info[0]; const price42 = p42.t0 === USDT_INF ? p42.r0 / p42.r1 : p42.r1 / p42.r0;
  // QOM/42: QOM per 42
  const pQ = info[1]; const qomPer42 = pQ.t0 === QOM_INF ? pQ.r0 / pQ.r1 : pQ.r1 / pQ.r0;
  const qomUsd = price42 / qomPer42;
  // FISH/USDT and FISH/QOM cross-check
  const pF = info[2]; const fishUsd = pF.t0 === FISH_INF ? pF.r1 / pF.r0 : pF.r0 / pF.r1;
  const pFQ = info[3]; const qomPerFish = pFQ.t0 === QOM_INF ? pFQ.r0 / pFQ.r1 : pFQ.r1 / pFQ.r0;
  const qomUsdViaFish = fishUsd / qomPerFish;
  return { price42, qomUsd, qomUsdViaFish, fishUsd };
}

async function fetchQl1Reference(qomUsd) {
  const pa = decPair(await rpcOne(QL1_RPC, QL1_FACTORY, SEL.getPair + encAddr(WQOM) + encAddr(QUSDT)));
  if (!pa) throw new Error(L("errQl1PoolMissing"));
  const res = await rpcBatch(QL1_RPC, [[pa, SEL.token0], [pa, SEL.getReserves]]);
  const t0 = decAddr(res[0]); const rr = parseReservesRaw(res[1]);
  if (!t0 || !rr) throw new Error(L("errQl1PoolReserves"));
  const r0 = bigToNum(rr[0], t0 === WQOM ? 18 : 6) || 0;
  const r1 = bigToNum(rr[1], t0 === WQOM ? 6 : 18) || 0;
  const qomQl1Pool = t0 === WQOM ? r1 / r0 : r0 / r1;
  return { qomQl1Pool, divergence: qomQl1Pool / qomUsd };
}

async function fetchBlockscout() {
  const holders = new Map(), icons = new Map(), list = [];
  let url = BS_API + "/tokens?type=ERC-20";
  for (let page = 0; page < 25 && url; page++) {
    const res = await fetch(url); if (!res.ok) break;
    const j = await res.json();
    for (const t of j.items || []) {
      const a = t.address_hash.toLowerCase();
      holders.set(a, t.holders_count != null ? Number(t.holders_count) : null);
      if (t.icon_url) icons.set(a, t.icon_url);
      list.push(t);
    }
    const nxt = j.next_page_params;
    if (!nxt) break;
    url = BS_API + "/tokens?type=ERC-20&" + new URLSearchParams(nxt).toString();
  }
  return { holders, icons, list };
}

function computePrices(pairs, meta, holdersMap, iconsMap, anchors) {
  const dec = (a) => { const m = meta.get(a); return m && m.decimals != null ? m.decimals : 18; };
  const sym = (a) => { const m = meta.get(a); return (m && m.symbol) || "?"; };
  const pairAddrs = new Set(pairs.map((p) => p.pair));
  const human = pairs.map((p) => ({
    pair: p.pair, t0: p.token0, t1: p.token1,
    r0: bigToNum(p.reserve0, dec(p.token0)) || 0, r1: bigToNum(p.reserve1, dec(p.token1)) || 0,
    lpSupply: p.lpSupplyRaw ? bigToNum(p.lpSupplyRaw, 18) : null,
  }));
  const anchorMap = new Map([
    [WQOM, { usd: anchors.qomUsd, label: L("anchorInfinite") }],
    [QUSDT, { usd: 1, label: L("anchorFixed") }], [QUSDC, { usd: 1, label: L("anchorFixed") }], [QDAI, { usd: 1, label: L("anchorFixed") }],
  ]);
  function direct(amap) {
    const best = new Map(), all = new Map();
    for (const pr of human) {
      for (const [known, unk, rk, ru] of [[pr.t0, pr.t1, pr.r0, pr.r1], [pr.t1, pr.t0, pr.r1, pr.r0]]) {
        const ka = amap.get(known);
        if (!ka || rk <= 0 || ru <= 0) continue;
        const liq = rk * ka.usd;
        if (liq < 0.5) continue;
        const cand = { usd: ka.usd * rk / ru, route: sym(unk) + "→" + sym(known), via: sym(known), liq, pair: pr.pair, reserveKnown: rk, reserveToken: ru };
        if (!all.has(unk)) all.set(unk, []);
        all.get(unk).push(cand);
        if (!best.has(unk) || liq > best.get(unk).liq) best.set(unk, cand);
      }
    }
    return { best, all };
  }
  let { best, all } = direct(anchorMap);
  for (const [a, b] of best) {
    const cs = all.get(a) || [];
    if (cs.length >= 2) {
      const ps = cs.map((c) => c.usd);
      if (Math.max(...ps) / Math.min(...ps) > 3) best.set(a, { ...b, diverge: cs.map((c) => ({ via: c.via, usd: c.usd, liq: c.liq })) });
    }
  }
  const inter = new Map(anchorMap);
  for (const [a, b] of best) if (b.liq >= 500 && !anchorMap.has(a) && !b.diverge) inter.set(a, { usd: b.usd, label: L("hop2Label") });
  const second = direct(inter);
  for (const [a, c] of second.best) if (!best.has(a) && !anchorMap.has(a)) best.set(a, { ...c, hop: 2, route: c.route + L("routeToAnchorSuffix") });
  for (const [a, av] of anchorMap) best.set(a, { usd: av.usd, route: av.label, via: L("viaAnchor"), liq: null, pair: null });
  const supply = (a) => { const m = meta.get(a); return m && m.totalSupply != null ? bigToNum(m.totalSupply, dec(a)) : null; };
  const tokens = [];
  for (const [addr, info] of best) {
    const m = meta.get(addr) || {};
    const s = supply(addr);
    tokens.push({
      address: addr, symbol: m.symbol || "?", name: m.name || "", decimals: dec(addr), totalSupply: s,
      holders: holdersMap.get(addr) != null ? holdersMap.get(addr) : null, icon: iconsMap.get(addr) || null,
      priceUsd: info.usd, priceQom: addr === WQOM ? 1 : info.usd / anchors.qomUsd,
      mcap: s != null ? info.usd * s : null, route: info.route, via: info.via || null, pair: info.pair || null,
      liqUsd: info.liq != null ? info.liq : null, hop: info.hop || 1,
      reserveKnown: info.reserveKnown != null ? info.reserveKnown : null, reserveToken: info.reserveToken != null ? info.reserveToken : null,
      diverge: info.diverge || null, isLP: pairAddrs.has(addr),
    });
  }
  const pmap = new Map(tokens.map((t) => [t.address, t.priceUsd]));
  for (const pr of human) {
    if (pmap.has(pr.pair)) continue;
    const p0 = pmap.get(pr.t0), p1 = pmap.get(pr.t1);
    if (p0 != null && p1 != null && pr.lpSupply) {
      const val = pr.r0 * p0 + pr.r1 * p1;
      if (val >= 0.5) {
        const m = meta.get(pr.pair) || {};
        tokens.push({
          address: pr.pair, symbol: m.symbol || "QSWAP-V2", name: "QomSwap LP " + sym(pr.t0) + "/" + sym(pr.t1),
          decimals: 18, totalSupply: pr.lpSupply, holders: holdersMap.get(pr.pair) != null ? holdersMap.get(pr.pair) : null,
          icon: iconsMap.get(pr.pair) || null, priceUsd: val / pr.lpSupply, priceQom: (val / pr.lpSupply) / anchors.qomUsd,
          mcap: val, route: L("lpBacked", sym(pr.t0), sym(pr.t1)), via: "LP", pair: pr.pair,
          liqUsd: val / 2, hop: 1, reserveKnown: null, reserveToken: null, diverge: null, isLP: true,
        });
      }
    }
  }
  tokens.sort((x, y) => (y.mcap || 0) - (x.mcap || 0));
  return tokens;
}

/* === WORKER GLUE === */
/* Refreshes the full QL1 price dataset from both chains into KV every
   minute (cron). The site fetches this one JSON instead of making
   ~2,600 RPC reads from the visitor's phone. If the cache is missing,
   the first fetch computes it inline; if it is older than 2 minutes, a
   fetch serves the stale copy and refreshes in the background. */

const PRICES_KEY = "prices:v1";
const BSLIST_KEY = "bslist:v1";
const BSLIST_TTL_MS = 10 * 60 * 1000;

async function mapPool(items, limit, fn) {
  let idx = 0;
  async function run() {
    while (idx < items.length) {
      const i = idx++;
      await fn(items[i], i);
    }
  }
  await Promise.all(Array.from({ length: Math.min(limit, items.length) }, run));
}

async function getBsList(env) {
  try {
    const raw = await env.PRICES_KV.get(BSLIST_KEY);
    if (raw) {
      const j = JSON.parse(raw);
      if (Date.now() - j.at < BSLIST_TTL_MS && j.data && j.data.list) return j.data;
    }
  } catch (e) { /* fall through to a fresh fetch */ }
  const bs = await fetchBlockscout();
  const data = { holders: [...bs.holders], icons: [...bs.icons], list: bs.list };
  try { await env.PRICES_KV.put(BSLIST_KEY, JSON.stringify({ at: Date.now(), data })); } catch (e) {}
  return data;
}

async function refresh(env) {
  const anchors = await fetchAnchors();
  const ref = await fetchQl1Reference(anchors.qomUsd);
  Object.assign(anchors, ref);

  const lenRes = await rpcOne(QL1_RPC, QL1_FACTORY, SEL.allPairsLength);
  const nPairs = Number(decUint(lenRes));
  let pairAddrs = [];
  await mapPool(chunks([...Array(nPairs).keys()], 100), 4, async (c) => {
    const rs = await rpcBatch(QL1_RPC, c.map((i) => [QL1_FACTORY, SEL.allPairs + encUint(i)]));
    pairAddrs.push(...rs.map(decAddr));
  });
  pairAddrs = pairAddrs.filter(Boolean);

  const pairs = [];
  await mapPool(chunks(pairAddrs, 100), 4, async (c) => {
    const calls = [];
    for (const p of c) calls.push([p, SEL.token0], [p, SEL.token1], [p, SEL.getReserves], [p, SEL.totalSupply]);
    const rs = await rpcBatch(QL1_RPC, calls);
    c.forEach((p, i) => {
      const t0 = decAddr(rs[i * 4]), t1 = decAddr(rs[i * 4 + 1]);
      const rr = parseReservesRaw(rs[i * 4 + 2]);
      if (!p || !t0 || !t1 || !rr) return;
      pairs.push({ pair: p, token0: t0, token1: t1, reserve0: rr[0], reserve1: rr[1], lpSupplyRaw: decUint(rs[i * 4 + 3]) });
    });
  });

  /* Metadata: Blockscout first (cached 10 min), on-chain only for the
     tokens Blockscout does not know. */
  const bsData = await getBsList(env);
  const holders = new Map(bsData.holders), icons = new Map(bsData.icons);
  const bsByAddr = new Map(bsData.list.map((t) => [t.address_hash.toLowerCase(), t]));
  const uniq = [...new Set(pairs.flatMap((p) => [p.token0, p.token1]))];
  const meta = new Map();
  const missing = [];
  for (const t of uniq) {
    const b = bsByAddr.get(t);
    if (b) meta.set(t, {
      symbol: b.symbol || null, name: b.name || null,
      decimals: b.decimals != null ? Number(b.decimals) : null,
      totalSupply: b.total_supply ? BigInt(b.total_supply) : null,
    });
    else missing.push(t);
  }
  await mapPool(chunks(missing, 50), 4, async (c) => {
    const calls = [];
    for (const t of c) calls.push([t, SEL.symbol], [t, SEL.name], [t, SEL.decimals], [t, SEL.totalSupply]);
    const rs = await rpcBatch(QL1_RPC, calls);
    c.forEach((t, i) => meta.set(t, {
      symbol: decStr(rs[i * 4]), name: decStr(rs[i * 4 + 1]),
      decimals: rs[i * 4 + 2] ? Number(decUint(rs[i * 4 + 2])) : null,
      totalSupply: decUint(rs[i * 4 + 3]),
    }));
  });

  const tokens = computePrices(pairs, meta, holders, icons, anchors);
  const pricedAddrs = new Set(tokens.map((t) => t.address));
  const pairAddrSet = new Set(pairAddrs);
  const unpriced = [];
  for (const t of bsData.list) {
    const a = t.address_hash.toLowerCase();
    if (!pricedAddrs.has(a)) unpriced.push({
      address: a, symbol: t.symbol, name: t.name,
      holders: t.holders_count != null ? Number(t.holders_count) : null,
      totalSupply: t.total_supply ? bigToNum(BigInt(t.total_supply), t.decimals ? Number(t.decimals) : 18) : null,
      isLP: pairAddrSet.has(a),
    });
  }
  unpriced.sort((x, y) => (y.holders || 0) - (x.holders || 0));
  const [infBlock, ql1Block] = await Promise.all([rpcBlock(INF_RPC), rpcBlock(QL1_RPC)]);
  const data = {
    anchors, tokens, unpriced,
    stats: { ql1Pairs: nPairs, bsTokens: bsData.list.length, priced: tokens.length, unpriced: unpriced.length },
    generatedAt: new Date().toISOString(), source: "cache", infBlock, ql1Block,
  };
  await env.PRICES_KV.put(PRICES_KEY, JSON.stringify(data));
  return data;
}

function jsonResponse(o, status) {
  return new Response(JSON.stringify(o), {
    status: status || 200,
    headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" },
  });
}

async function recordDebug(env, key, ok, err) {
  try {
    await env.PRICES_KV.put("debug:" + key, JSON.stringify({
      at: new Date().toISOString(), ok, err: err ? String((err && err.message) || err) : null,
    }));
  } catch (e) { /* debug only */ }
}

export default {
  async scheduled(event, env, ctx) {
    ctx.waitUntil((async () => {
      try { await refresh(env); await recordDebug(env, "cron", true, null); }
      catch (e) { await recordDebug(env, "cron", false, e); }
    })());
  },
  async fetch(req, env, ctx) {
    const url = new URL(req.url);
    if (url.pathname === "/debug") {
      const cron = await env.PRICES_KV.get("debug:cron");
      return jsonResponse({ cron: cron ? JSON.parse(cron) : null });
    }
    if (url.pathname === "/status") {
      const raw = await env.PRICES_KV.get(PRICES_KEY);
      if (!raw) return jsonResponse({ ok: false, error: "cache empty" }, 503);
      const j = JSON.parse(raw);
      return jsonResponse({
        ok: true, generatedAt: j.generatedAt, infBlock: j.infBlock, ql1Block: j.ql1Block,
        priced: j.stats.priced, unpriced: j.stats.unpriced, qomUsd: j.anchors.qomUsd, price42: j.anchors.price42,
      });
    }
    if (url.pathname === "/" || url.pathname === "/prices") {
      let raw = await env.PRICES_KV.get(PRICES_KEY);
      if (!raw) {
        try {
          await refresh(env);
          raw = await env.PRICES_KV.get(PRICES_KEY);
        } catch (e) {
          return jsonResponse({ ok: false, error: String((e && e.message) || e) }, 502);
        }
      } else {
        try {
          const j = JSON.parse(raw);
          if (Date.now() - new Date(j.generatedAt).getTime() > 120000) {
            ctx.waitUntil(refresh(env).catch(() => {}));
          }
        } catch (e) { /* serve what we have */ }
      }
      return new Response(raw, {
        headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*", "Cache-Control": "no-store" },
      });
    }
    return new Response("not found", { status: 404 });
  },
};

